{
    public const string OriginalSha256 = "A42AA9F0A551EC0BAACDD02DA3351F13B6F7538E7C0068D7516EECD9BB073C4A";
    public const string PatchedSha256 = "B77E36BBBC747B5BA88C918B9B20EB15AC3023108832F3B764F25A97FE74E204";
    public const int OriginalSize = 75408;
    public const int PatchedSize = 127796;

    public static byte[] Get(bool enabled)
    {
        int expected = enabled ? PatchedSize : OriginalSize;
        byte[] compressed = Convert.FromBase64String(enabled ? PatchedDeflate : OriginalDeflate);
        byte[] result = new byte[expected];
        using (var input = new MemoryStream(compressed, false))
        using (var deflate = new DeflateStream(input, CompressionMode.Decompress))
        {
            int offset = 0;
            while (offset < result.Length)
            {
                int count = deflate.Read(result, offset, result.Length - offset);
                if (count == 0) throw new InvalidDataException("Truncated embedded menu badge.");
                offset += count;
            }
            if (deflate.ReadByte() != -1) throw new InvalidDataException("Oversized embedded menu badge.");
        }
        if (Hash(result) != (enabled ? PatchedSha256 : OriginalSha256))
            throw new InvalidDataException("Embedded menu badge SHA256 mismatch.");
        return result;
    }

    public static string Hash(byte[] data)
    {
        using (var sha = SHA256.Create())
            return BitConverter.ToString(sha.ComputeHash(data)).Replace("-", "");
    }
